PROCEDURE Factorial(i: LONGINT): LONGINT;
VAR
BEGIN
    IF i < 0 THEN i := -i  END;
    IF i < 2 THEN
        RETURN i
    ELSE
        RETURN i * Factorial(i - 1)
    END
END Factorial;

