# i64 can represent n! for 0 <= n <= 20.
# Return -1 for an argument outside that range.
fun factorial_iterative(n: i64) -> i64 = {
    if (n < 0 or n > 20) return -1;
    var result: i64 = 1;
    var factor: i64 = 2;
    while (factor <= n) {
        result = result * factor;
        factor = factor + 1;
    }
    return result;
}

fun factorial_recursive(n: i64) -> i64 = {
    if (n < 0 or n > 20) return -1;
    if (n == 0) return 1;
    return n * factorial_recursive(n - 1);
}

