function factorial(n) {
  // factorial is only defined for non-negative integers
  if (n < 0 || !Number.isInteger(n)) return NaN;

  let result = 1;

  // we skip zero and one since both are 1 and are identity
  while (n > 1) {
    result *= n;
    n--;
  }

  return result;
}

